import{z as i,x as l,o as t,c as p,q as A,j as s,D as e,d as r,s as o,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"假设与预注册","description":"","frontmatter":{"title":"假设与预注册","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hypothesis-preregistration.md","filePath":"quant/hypothesis-preregistration.md","lastUpdated":1791413859000}'),d={name:"quant/hypothesis-preregistration.md"};function h(u,a,D,f,m,g){const n=l("Mermaid");return t(),p("div",null,[a[2]||(a[2]=A('<h1 id="假设与预注册" tabindex="-1">假设与预注册 <a class="header-anchor" href="#假设与预注册" aria-label="Permalink to &quot;假设与预注册&quot;">​</a></h1><div class="epigraph"><p>第一原则是不要欺骗自己——而你自己恰恰是最容易被骗的人。</p><footer>—— Feynman, &quot;Cargo Cult Science&quot;, 加州理工学院毕业典礼演讲, 1974</footer></div><p><a href="/quant/research-question-origination">上一课</a>把观察收成带拒绝条件的可检验问题，并用经济逻辑、可证伪、成本可行三道闸立项。本课把立项变成合同：主假设、次要假设、终止规则，全部写在碰数据之前。立场是<a href="/quant/backtest-overfitting">过拟合次数与试错</a>的推论——错误不在试错，而在试错不计次；预注册就是计次装置。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>从「问题成立」到「写出回测」之间隔着几十个自由度：universe 怎么划、样本从哪年起、持有期取二十天还是六十天、SUE 的预期盈利用哪种模型、要不要中性化、成本假设取宽取紧。每个选择都是一个试验位。Gelman 与 Loken 的「分岔小径」说得更狠：即便你没有恶意挖参，只要选择是看完数据后做出的，整棵决策树就都参与了检验，而报告里只写了走通的那条枝。<a href="/quant/multiple-testing-factors">多重检验与 p-hacking</a> 解释这为何抬高假阳性，<a href="/quant/pbo">Probability of Backtest Overfitting</a> 解释它如何精确毁掉「选最优变体」这件事。缺口不是「更小心」，而是把选择搬到数据之前并留痕。</p><p><span class="marginnote">「自由度」在统计里本指能独立变动的量的个数，这里借指研究者能自由拍板的每一个设置。初学者容易以为只有「换个参数重跑」才算多次试验，实际上换一个样本起点、换一种中性化方式，同样等价于多检验了一次——每个选择都在消耗同一份运气的额度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>注册文档在碰数据前冻结，最少四个字段。<strong>主假设</strong>：方向、检验统计量、显著性门槛（按家族口径定，不是每次单独 0.05）、样本期、universe 与排除规则、再平衡频率与成本假设。<strong>次要假设清单</strong>：允许探索，但逐条标注「探索性」，不得进入主结论。<strong>终止规则</strong>：主假设在样本外不成立即终止，不许「换一个变换再试一次」——这是研究者自己的止损线，量化研究的沉没成本错觉比交易里更凶。<strong>偏离记录</strong>：任何与注册文档不符之处写入台账，不悄悄改。</p><p><span class="marginnote">「按家族口径定门槛」是什么意思：把一族相关检验捆在一起控制误报率。数字实例：若族里有 10 次近似独立的检验，想让「至少一次误报」的概率仍压在 5%，单次门槛就得用 Bonferroni 收紧到 0.05 ÷ 10 = 0.005，对应 t 临界值约 2.8——这正是逐次用 0.05（t=2）看似显著、实则大半是噪声的原因。</span></p><p>对 PEAD 案例，主假设一次写完：SUE 十分组多空（多最高组、空最低组），行业与市值中性，公告后六十个交易日持有，月度滚动，成本按<a href="/quant/spread-cost">买卖价差成本</a>的历史中位数加冲击，门槛取家族校正后的 t。</p><h3 id="注册文档喂给下游什么" tabindex="-1">注册文档喂给下游什么 <a class="header-anchor" href="#注册文档喂给下游什么" aria-label="Permalink to &quot;注册文档喂给下游什么&quot;">​</a></h3><p>预注册不是道德姿态，它产出下游统计的输入：<strong>试验次数 N</strong>。<a href="/quant/deflated-sharpe">Deflated Sharpe</a> 要拿 N 与各次试验 Sharpe 的方差做缩水；<a href="/quant/cscv">CSCV 组合对称交叉验证</a>与 PBO 要回答「选中的变体是不是运气最好的那个」。N 从注册文档与偏离记录里来。没有预注册，N 就是「不记得试了多少次」，一切修正量失效——这是预注册与多重检验纪律的接口。</p><p><span class="marginnote">Harvey、Liu 与 Zhu 数过顶刊与工作论文里被当作异象提出的因子：三百多个。他们建议新异象的 t 门槛至少 3.0——t=2 的名义门槛属于「一篇文献只检验一个假设」的旧世界。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2>',14)),(t(),s(B,null,{default:e(()=>[o(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E6%B3%A8%E5%86%8C%E6%96%87%E6%A1%A3%EF%BC%9A%E4%B8%BB%E5%81%87%E8%AE%BE%20%2B%20%E6%AC%A1%E8%A6%81%E6%B8%85%E5%8D%95%20%2B%20%E7%BB%88%E6%AD%A2%E8%A7%84%E5%88%99%22%5D%20--%3E%20DATA%5B%22%E6%AD%A4%E5%90%8E%E6%89%8D%E5%85%81%E8%AE%B8%E7%A2%B0%E6%95%B0%E6%8D%AE%22%5D%0A%20%20DATA%20--%3E%20PATH%5B%22%E6%89%A7%E8%A1%8C%E6%B3%A8%E5%86%8C%E8%B7%AF%E5%BE%84%22%5D%0A%20%20PATH%20--%3E%20REPORT%5B%22%E6%8A%A5%E5%91%8A%EF%BC%9A%E6%B3%A8%E5%86%8C%E7%BB%93%E6%9E%9C%20%2B%20%E5%81%8F%E7%A6%BB%E8%AE%B0%E5%BD%95%22%5D%0A%20%20DATA%20--%3E%20FORK%5B%22%E6%9C%AA%E6%B3%A8%E5%86%8C%E5%B2%94%E8%B7%AF%EF%BC%9A%E5%8F%98%E6%8D%A2%20%2F%20%E7%AA%97%E5%8F%A3%20%2F%20universe%22%5D%0A%20%20FORK%20--%3E%20N%5B%22%E5%8F%B0%E8%B4%A6%E8%AE%A1%E6%AC%A1%EF%BC%9AN%22%5D%0A%20%20N%20--%3E%20DSR%5B%22%E5%96%82%E7%BB%99%20DSR%20%2F%20PBO%20%E5%81%9A%E7%BC%A9%E6%B0%B4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<p>机制上，预注册改变的是<strong>选择与信息的时间顺序</strong>。数据之后的选择以数据为条件，独立性破产，报告的 p 值不再指向假设本身；数据之前的选择与噪声无关，检验才有效力。终止规则把「再试一次」的成本显式化：每次偏离记账为 N 加一，而 N 加一直接抬高下一轮修正的门槛。注册文档因此是可审计的——偏离必须留痕，审计者或半年后的你能重建整棵决策树。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>预注册不担保假设正确，只担保检验诚实；坏问题注册一万次也是坏问题。探索性研究合法且必要——新直觉大多来自看数据——但探索与确认必须分开：探索的出口是下一个<strong>新样本上的注册</strong>，不是同一个样本上的更好故事。机构里执行靠两件东西：模板（空字段比忘字段更容易被发现）与代码冻结（<a href="/quant/xalpha-hypothesis-code">XAlpha：假设到代码</a>那种把假设句直接映射成实现的口径）。也别把注册当圣旨：发现实现错误就修，修了就记——纪律针对的是隐瞒，不是迭代。</p><p><span class="marginnote">「代码冻结」指注册文档定稿的同时，实现代码也锁定版本，之后只许修 bug、不许改策略。为什么重要：若文档冻结而代码还能随手改，研究者的自由度只是从参数搬进了代码里，计次装置等于被整个绕过——台账里记的 N 就不再覆盖真实发生过的试验。</span></p>',4)),(t(),s(B,null,{default:e(()=>[o(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20OLD%5B%22%E6%97%A7%E6%A0%B7%E6%9C%AC%EF%BC%9A%E8%87%AA%E7%94%B1%E6%8E%A2%E7%B4%A2%22%5D%20--%3E%20IDEA%5B%22%E5%86%92%E5%87%BA%E6%96%B0%E7%9B%B4%E8%A7%89%E5%81%87%E8%AE%BE%22%5D%0A%20%20IDEA%20--%3E%20REG%5B%22%E5%86%99%E6%B3%A8%E5%86%8C%E6%96%87%E6%A1%A3%E5%B9%B6%E5%86%BB%E7%BB%93%22%5D%0A%20%20REG%20--%3E%20NEW%5B%22%E6%8D%A2%E4%B8%80%E6%89%B9%E6%9C%AA%E8%A7%81%E8%BF%87%E7%9A%84%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20NEW%20--%3E%20TEST%7B%22%E6%B3%A8%E5%86%8C%E6%A3%80%E9%AA%8C%E9%80%9A%E8%BF%87%EF%BC%9F%22%7D%0A%20%20TEST%20--%20%22%E6%98%AF%22%20--%3E%20OK%5B%22%E8%BF%9B%E5%85%A5%E4%B8%BB%E7%BB%93%E8%AE%BA%22%5D%0A%20%20TEST%20--%20%22%E5%90%A6%22%20--%3E%20STOP%5B%22%E7%BB%88%E6%AD%A2%E6%88%96%E9%87%8D%E6%96%B0%E7%AB%8B%E9%A1%B9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E("p",null,"探索的出口是新样本上的再注册，而不是旧数据上的更好故事——上图正是这条合法循环。",-1)),a[5]||(a[5]=E("h2",{id:"小结",tabindex:"-1"},[r("小结 "),E("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[6]||(a[6]=E("ul",null,[E("li",null,"预注册把研究自由度搬到碰数据之前并留痕，本质是给试错计次。"),E("li",null,"四件套：主假设（含门槛与成本假设）、次要探索清单、终止规则、偏离记录。"),E("li",null,"注册文档的产出 N 是 DSR / PBO 的输入；没有 N，修正全部作废。"),E("li",null,"探索合法，但出口是新样本上的再注册，不是同一数据的更好故事。"),E("li",null,"出处：Feynman (1974)；Gelman and Loken (2013)；Nosek et al. (2018) 对预注册运动的综述；Harvey, Liu and Zhu (2016)。")],-1))])}const q=i(d,[["render",h]]);export{c as __pageData,q as default};
